```vue client/src/views/DesktopView.vue
<script setup>
import Desktop from '@/components/desktop/Desktop.vue'
</script>
<template>
  <div class="w-full h-full @container group-codxjunior">
    <Desktop
      :panels="panels"
      @ready="onDesktopReady"
      @layout-saved="onLayoutSaved"
      ref="desktop"
    />
  </div>
</template>
<script>
const STORAGE_KEY = 'desktop-layout'

export default {
  name: 'DesktopView',
  data() {
    return {
      panelsApi: null,
      panels: []
    }
  },
  computed: {
    apps() {
      return Object.values(this.$ui.openApps)
    },
    appKeys() {
      return this.apps.map(({ key }) => key)
    },
    panelKeys() {
      return this.panels.map(({ id }) => id)
    }
  },
  watch: {
    apps(newVal) {
      const { panelKeys } = this
      newVal
        .filter(({ key }) => !panelKeys.includes(key))
        .forEach(app => this.addAppPanel(app))
    }
  },
  mounted() {
    this.loadSavedLayout()
  },
  methods: {
    onDesktopReady({ api }) {
      this.panelsApi = api
      this.panelsApi.onDidAddPanel(this.onDidAddPanel.bind(this))
      this.panelsApi.onDidRemovePanel(this.onDidRemovePanel.bind(this))
      this.panelsApi.onDidLayoutChange(this.saveLayout.bind(this))
      // Restore saved layout or open current apps
      const restored = this.restoreLayout()
      if (!restored) {
        this.apps.forEach(app => this.addAppPanel(app))
      }
    },
    addAppPanel(app) {
      if (!app?.key) return
      this.panelsApi.addPanel({
        id: app.key,
        title: app.name,
        component: app.component || 'app-window',
        params: {
          ...app.params || {},
          app
        }
      })
    },
    onDidAddPanel(panel) {
      this.panels.push(panel)
    },
    onDidRemovePanel(panel) {
      this.$ui.closeApp(panel.params.app)
      this.panels = this.panels.filter(p => p !== panel)
    },
    onLayoutSaved(layout) {
      // Relay layout-saved event upward if needed
      this.$emit('layout-saved', layout)
    },
    // Persist current dockview layout to localStorage
    saveLayout() {
      if (!this.panelsApi) return
      try {
        const layout = this.panelsApi.toJSON()
        localStorage.setItem(STORAGE_KEY, JSON.stringify(layout))
      } catch (e) {
        console.warn('Failed to save desktop layout:', e)
      }
    },
    // Load and return saved layout JSON from localStorage
    loadSavedLayout() {
      try {
        const raw = localStorage.getItem(STORAGE_KEY)
        return raw ? JSON.parse(raw) : null
      } catch (e) {
        console.warn('Failed to load desktop layout:', e)
        return null
      }
    },
    // Restore saved layout into dockview, returns true on success
    restoreLayout() {
      if (!this.panelsApi) return false
      const layout = this.loadSavedLayout()
      if (!layout) return false
      try {
        this.panelsApi.fromJSON(layout)
        return true
      } catch (e) {
        console.warn('Failed to restore desktop layout:', e)
        return false
      }
    },
    clearLayout() {
      localStorage.removeItem(STORAGE_KEY)
    }
  }
}
</script>
```

### Key changes

| Change | Details |
|--------|---------|
| **Save on layout change** | `onDidLayoutChange` listener calls `saveLayout()` which serializes via `panelsApi.toJSON()` and writes to `localStorage` |
| **Restore on ready** | `restoreLayout()` is called inside `onDesktopReady` — if it succeeds, initial app panels are skipped to avoid duplicates |
| **`loadSavedLayout()`** | Utility method that safely reads & parses from `localStorage` |
| **`clearLayout()`** | Helper to wipe the saved layout if needed |
| **Separate `STORAGE_KEY`** | Uses `'desktop-layout'` key scoped to this view, independent of `Desktop.vue`'s own key |
